fn solve(n: i8, s: Vec<char>) -> i8 {
    // If there's fewer than 2 characters, there can't be any adjacent equal pairs.
    if n < 2 {
        return 0;
    }

    let mut count: i8 = 0;
    // s.len() == n as usize by problem statement
    let len = s.len();
    // Iterate from 0 to len-2 (inclusive)
    for i in 0..len - 1 {
        if s[i] == s[i + 1] {
            count += 1;
        }
    }
    count
}

// Example usage and basic test
fn main() {
    let s1: Vec<char> = "aabbba".chars().collect();
    assert_eq!(solve(6, s1), 3);  // pairs: (0,1)->'a','a'; (2,3)->'b','b'; (3,4)->'b','b'

    let s2: Vec<char> = "abcdef".chars().collect();
    assert_eq!(solve(6, s2), 0);  // no adjacent equal characters

    let s3: Vec<char> = "zz".chars().collect();
    assert_eq!(solve(2, s3), 1);  // one pair 'z','z'

    let s4: Vec<char> = "x".chars().collect();
    assert_eq!(solve(1, s4), 0);  // only one character, no pairs

    println!("All tests passed!");
}